SELECT a.Version,a.Revision,a.ReceiptSequence,a.PurchaseSequence
,JSON_QUERY((SELECT p.[Id],p.[Name],p.[Category],p.[Price],p.[Active],p.[ImagePath],p.[Instructions] FROM dbo.[MenuItems] p ORDER BY p.[Id] FOR JSON PATH)) AS [Foods]
,JSON_QUERY((SELECT p.[Id],p.[Name],p.[Unit],p.[Stock],p.[Minimum],p.[AverageCost] FROM dbo.[Ingredients] p ORDER BY p.[Id] FOR JSON PATH)) AS [Ingredients]
,JSON_QUERY((SELECT p.[Id],p.[Name],p.[Price],p.[Active] FROM dbo.[ExtraServices] p ORDER BY p.[Id] FOR JSON PATH)) AS [Services]
,JSON_QUERY((SELECT p.[Id],p.[Name],p.[Seats] FROM dbo.[DiningTables] p ORDER BY p.[Id] FOR JSON PATH)) AS [Tables]
,JSON_QUERY((SELECT p.[FoodId],p.[IngredientId],p.[Quantity] FROM dbo.[RecipeIngredients] p ORDER BY p.[FoodId] FOR JSON PATH)) AS [Recipes]
,JSON_QUERY((SELECT p.[Id],p.[TableId],p.[Customer],p.[Phone],p.[Time],p.[Guests],p.[Status] FROM dbo.[TableReservations] p ORDER BY p.[Id] FOR JSON PATH)) AS [Reservations]
,JSON_QUERY((SELECT p.[Id],p.[Date],p.[Supplier],p.[Operator],JSON_QUERY((SELECT l.[IngredientId],l.[Name],l.[Unit],l.[Quantity],l.[UnitCost] FROM dbo.[StockReceiptItems] l WHERE l.[PurchaseId]=p.Id ORDER BY l.[LineNo] FOR JSON PATH)) AS [Lines] FROM dbo.[StockReceipts] p ORDER BY p.[Id] FOR JSON PATH)) AS [Purchases]
,JSON_QUERY((SELECT p.[Id],p.[TableId],p.[TableName],p.[Customer],p.[Operator],p.[CreatedAt],p.[PaidAt],p.[Status],p.[Discount],p.[PaymentMethod],p.[Received],JSON_QUERY((SELECT l.[FoodId],l.[Name],l.[Quantity],l.[UnitPrice],l.[Note] FROM dbo.[SalesOrderItems] l WHERE l.[OrderId]=p.Id ORDER BY l.[LineNo] FOR JSON PATH)) AS [Lines],JSON_QUERY((SELECT l.[ServiceId],l.[Name],l.[Quantity],l.[UnitPrice] FROM dbo.[SalesOrderServices] l WHERE l.[OrderId]=p.Id ORDER BY l.[LineNo] FOR JSON PATH)) AS [Extras] FROM dbo.[SalesOrders] p ORDER BY p.[Id] FOR JSON PATH)) AS [Sales]
FROM dbo.ApplicationState a WITH (HOLDLOCK) WHERE a.Id=1 FOR JSON PATH,WITHOUT_ARRAY_WRAPPER;